#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stddef.h>  /* for size_t */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* Tunable blocking factors for the GEMM kernel.
 * They can be overridden at compile time, e.g.:
 *   gcc -O3 -DGEMM_TILE_I=64 -DGEMM_TILE_J=256 -DGEMM_TILE_K=32 ...
 *
 * The chosen defaults are conservative and work well on modern x86-64 CPUs.
 */
#ifndef GEMM_TILE_I
# define GEMM_TILE_I 32
#endif

#ifndef GEMM_TILE_J
# define GEMM_TILE_J 128
#endif

#ifndef GEMM_TILE_K
# define GEMM_TILE_K 32
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Separate scaling of C by beta in a single cache-friendly pass.
   - Explicit tiling (blocking) in i, j, and k dimensions to improve
     cache reuse of A, B, and C.
   - Use of restrict-qualified local aliases for A, B, and C to help
     the compiler with vectorization and alias analysis.
   - Hoisting of alpha * A[i][k] out of the innermost j-loop to reduce
     the number of floating-point multiplications.
   - Optional OpenMP parallelization over the outermost tiles; the
     pragmas are ignored unless the code is compiled with -fopenmp.
 */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Create restrict-qualified aliases for better optimization.
   * We only use C_, A_, and B_ below; the original parameter names
   * are not accessed again, which keeps the restrict contract valid.
   */
  DATA_TYPE (*restrict C_)[nj] = C;
  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;

  /* Effective loop bounds as used by PolyBench. */
  const int ni_eff = _PB_NI;
  const int nj_eff = _PB_NJ;
  const int nk_eff = _PB_NK;

#pragma scop

  /* 1. Scale C by beta.
   *
   * This is mathematically identical to the original code, which scaled
   * each row of C before performing the matrix multiplication for that row.
   * Here we perform the scaling for the entire matrix first; the operations
   * on different elements of C are independent, so the final result is the
   * same for every element C[i][j].
   */
  #pragma omp parallel for if ((size_t)ni_eff * (size_t)nj_eff > (size_t)256 * 256) schedule(static)
  for (int i = 0; i < ni_eff; ++i)
  {
    DATA_TYPE *restrict c_row = &C_[i][0];
    for (int j = 0; j < nj_eff; ++j)
      c_row[j] *= beta;
  }

  /* 2. Tiled GEMM: C += alpha * A * B
   *
   * Loop structure:
   *   for ii in tiles of i
   *     for kk in tiles of k
   *       for jj in tiles of j
   *         for k in kk-tile
   *           for i in ii-tile
   *             for j in jj-tile
   *
   * For a fixed (i, j), the contributions over k are accumulated in
   * increasing k order (0 .. nk_eff-1), as in the original kernel,
   * preserving the floating-point evaluation order for each element.
   *
   * The innermost loop walks j contiguously, which leads to sequential
   * access in both C and B and allows the compiler to vectorize it easily.
   */
  #pragma omp parallel for if ((size_t)ni_eff * (size_t)nj_eff * (size_t)nk_eff > (size_t)256 * 256 * 16) schedule(static)
  for (int ii = 0; ii < ni_eff; ii += GEMM_TILE_I)
  {
    const int i_end = (ii + GEMM_TILE_I < ni_eff) ? (ii + GEMM_TILE_I) : ni_eff;

    for (int kk = 0; kk < nk_eff; kk += GEMM_TILE_K)
    {
      const int k_end = (kk + GEMM_TILE_K < nk_eff) ? (kk + GEMM_TILE_K) : nk_eff;

      for (int jj = 0; jj < nj_eff; jj += GEMM_TILE_J)
      {
        const int j_end = (jj + GEMM_TILE_J < nj_eff) ? (jj + GEMM_TILE_J) : nj_eff;
        const int j_len = j_end - jj;

        /* Process a tile kk..k_end, ii..i_end, jj..j_end. */
        for (int k = kk; k < k_end; ++k)
        {
          const DATA_TYPE *restrict b_row = &B_[k][jj];

          for (int i = ii; i < i_end; ++i)
          {
            DATA_TYPE *restrict c_row = &C_[i][jj];
            const DATA_TYPE a_ik = alpha * A_[i][k];

            /* Innermost loop: contiguous j dimension.
             * This is the performance-critical part of the kernel.
             */
            for (int j = 0; j < j_len; ++j)
            {
              c_row[j] += a_ik * b_row[j];
            }
          }
        }
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
