 * They do not need to divide NI/NJ/NK; edge cases are handled explicitly.
 * ------------------------------------------------------------------- */
#ifndef GEMM_BLOCK_I
# define GEMM_BLOCK_I 64
#endif

#ifndef GEMM_BLOCK_J
# define GEMM_BLOCK_J 64
#endif

#ifndef GEMM_BLOCK_K
# define GEMM_BLOCK_K 64
#endif


