    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Effective loop bounds (may differ from NI/NJ/NK under some
     PolyBench configurations, so we keep using the _PB_* values). */
  const int ni_bound = _PB_NI;
  const int nj_bound = _PB_NJ;
  const int nk_bound = _PB_NK;

  /* Cache-tiling parameters (may be overridden via GEMM_BLOCK_I/J). */
  const int I_BLOCK = GEMM_BLOCK_I;
  const int J_BLOCK = GEMM_BLOCK_J;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* -------------------------------------------------------------------
   * Step 1: Scale C by beta.
   *
   * This is independent from A and B. We keep a simple, contiguous
   * row-wise traversal for good cache behavior and allow OpenMP
   * parallelization over rows.
   * -----------------------------------------------------------------*/
#pragma omp parallel for schedule(static)
  for (int i = 0; i < ni_bound; i++) {
    for (int j = 0; j < nj_bound; j++) {
      C[i][j] *= beta;
    }
  }

  /* -------------------------------------------------------------------
   * Step 2: Main GEMM computation: C += alpha * A * B
   *
   * Original code:
   *   for (i)
   *     for (k)
   *       for (j)
   *         C[i][j] += alpha * A[i][k] * B[k][j];
   *
   * Optimizations applied:
   *   - Loop reordering to k–i–j: for each k we reuse the contiguous
   *     row B[k][:] across all i, greatly improving B's cache reuse.
   *   - Tiling in i (I_BLOCK) and j (J_BLOCK) to keep working sets of
   *     C and B in caches.
   *   - Hoisting alpha*A[i][k] out of the innermost loop so that each
   *     A[i][k] is loaded and multiplied by alpha only once per (i,k).
   *   - Manual unrolling of the j loop by a factor of 4 to reduce loop
   *     overhead and help auto-vectorization.
   *   - OpenMP parallelization over tiles of the i dimension.
   *
   * Semantics:
   *   For each element C[i][j], we still perform:
   *     C[i][j] = beta * C[i][j]
   *               + sum_{k=0}^{nk_bound-1} alpha*A[i][k]*B[k][j]
   *   The contributions for a given (i,j) are accumulated in strictly
   *   increasing k order, exactly as in the original code. Only the
   *   relative order of updates to different C[i][j] (which are
   *   independent) changes.
   * -----------------------------------------------------------------*/
#pragma omp parallel
  {
    for (int k = 0; k < nk_bound; k++) {

      /* Pointer to row k of B, reused for all i for this k. */
      const DATA_TYPE *Bk = B[k];

      /* Parallelize over tiled i dimension. Each thread receives
         disjoint tiles of rows, so there is no overlap in C updates. */
#pragma omp for schedule(static)
      for (int ii = 0; ii < ni_bound; ii += I_BLOCK) {

        int i_end = ii + I_BLOCK;
        if (i_end > ni_bound)
          i_end = ni_bound;

        for (int jj = 0; jj < nj_bound; jj += J_BLOCK) {

          int j_end = jj + J_BLOCK;
          if (j_end > nj_bound)
            j_end = nj_bound;

          for (int i = ii; i < i_end; i++) {

            /* Row i of C and the corresponding block of B[k][:]. */
            DATA_TYPE *restrict Ci = &C[i][jj];
            const DATA_TYPE *restrict Bk_block = &Bk[jj];

            /* alpha * A[i][k] is reused across all j in this row. */
            const DATA_TYPE aik = alpha * A[i][k];

            const int len = j_end - jj;
            int j = 0;
            const int len_unroll = len & ~3; /* multiple of 4 */

            /* Unrolled inner loop over j for better vectorization. */
            for (; j < len_unroll; j += 4) {
              Ci[j    ] += aik * Bk_block[j    ];
              Ci[j + 1] += aik * Bk_block[j + 1];
              Ci[j + 2] += aik * Bk_block[j + 2];
              Ci[j + 3] += aik * Bk_block[j + 3];
            }

            /* Handle remaining columns (if len not divisible by 4). */
            for (; j < len; j++) {
              Ci[j] += aik * Bk_block[j];
            }
          } /* i */
        } /* jj */
      } /* ii */

      /* Implicit barrier at the end of the omp for ensures that all
         threads have completed updates for this value of k before
         the next k iteration begins, preventing races on C. */
    } /* k */
  } /* parallel region */

#pragma endscop

}


