/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Use local restrict-qualified aliases to help the compiler
     with alias analysis and to enable better vectorization. */
  DATA_TYPE (*restrict C_)[nj]       = C;
  const DATA_TYPE (*restrict A_)[nk] = A;
  const DATA_TYPE (*restrict B_)[nj] = B;

  /* Effective loop bounds as provided by PolyBench.  These may be
     equal to or smaller than the raw ni/nj/nk parameters depending
     on configuration, so we always use the _PB_* values in loops. */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;

  int i, j, k;

  //BLAS PARAMS
  //TRANSA = 'N'
  //TRANSB = 'N'
  // => Form C := alpha*A*B + beta*C,
  //A is NIxNK
  //B is NKxNJ
  //C is NIxNJ
#pragma scop

  /* ---------------------------------------------------------------------
   * 1. Scale C by beta: C = beta * C
   *
   * This loop is kept simple but uses a row pointer (Ci) to ensure
   * unit-stride access to C, which improves cache usage and lets
   * the compiler generate efficient SIMD code.
   * ------------------------------------------------------------------ */
  for (i = 0; i < ni_; i++) {
    DATA_TYPE *restrict Ci = C_[i];
    for (j = 0; j < nj_; j++) {
      Ci[j] *= beta;
    }
  }

  /* ---------------------------------------------------------------------
   * 2. Matrix multiplication with blocking:
   *
   *    C += alpha * A * B
   *
   * We apply a cache-friendly blocked algorithm over the (i, j, k)
   * iteration space. The blocking improves data locality by:
   *   - reusing rows of A and B in cache while updating a tile of C,
   *   - accessing C and B with unit stride inside the innermost loops.
   *
   * The blocking preserves the original arithmetic order with respect
   * to the k-accumulation for each element C[i][j]:
   *   - For each fixed (i, j), contributions are still added in
   *     increasing k order, exactly as in the original code.
   *
   * This keeps floating-point reduction semantics as close as possible
   * to the original implementation while significantly improving
   * data locality and vectorization opportunities.
   * ------------------------------------------------------------------ */
  for (int ii = 0; ii < ni_; ii += GEMM_BLOCK_I) {
    const int i_end = (ii + GEMM_BLOCK_I < ni_) ? (ii + GEMM_BLOCK_I) : ni_;

    for (int kk = 0; kk < nk_; kk += GEMM_BLOCK_K) {
      const int k_end = (kk + GEMM_BLOCK_K < nk_) ? (kk + GEMM_BLOCK_K) : nk_;

      for (int jj = 0; jj < nj_; jj += GEMM_BLOCK_J) {
        const int j_end = (jj + GEMM_BLOCK_J < nj_) ? (jj + GEMM_BLOCK_J) : nj_;

        /* Work on the tile:
         *   i in [ii, i_end)
         *   k in [kk, k_end)
         *   j in [jj, j_end)
         */
        for (i = ii; i < i_end; i++) {
          /* Pointer to the beginning of the current C tile row. */
          DATA_TYPE *restrict Ci_tile = &C_[i][jj];
          const DATA_TYPE *restrict Ai = A_[i];

          for (k = kk; k < k_end; k++) {
            const DATA_TYPE *restrict Bk_tile = &B_[k][jj];
            const DATA_TYPE a_ik = Ai[k];

            /* Inner-most loop: update a contiguous segment of C[i][*].
             * This is the main vectorization target.
             */
            for (j = 0; j < (j_end - jj); j++) {
              /* Keep the arithmetic expression identical to the
                 original implementation to preserve numerical
                 behavior as much as possible. */
              Ci_tile[j] += alpha * a_ik * Bk_tile[j];
            }
          }
        }
      }
    }
  }

#pragma endscop
}


